/* Explicit, one-tap power intentions; queued Combo resolves at actual move startup. */
(function(root){
'use strict';
const MAP={fire:{open:'d',launch:'f1',finish:'f',heavy:'e'},water:{open:'g',launch:'i',finish:'w2',heavy:'k'},earth:{open:'e1',launch:'a',finish:'c',heavy:'l'},wind:{open:'W',launch:'Z',finish:'V',heavy:'Z'},lightning:{open:'E',launch:'L',finish:'Q',heavy:'Q'},stretch:{open:'S',launch:'U',finish:'T',heavy:'R'}};
class QuickPowers{
 constructor(options){Object.assign(this,options);try{this.world.easyPowerKey=localStorage.getItem('kinetic-easy-power-key')==='true';}catch{}if(this.world.easyPowerKey)this.onKeyMode?.();document.getElementById('quick-extras').open=!window.matchMedia('(pointer:coarse)').matches;document.getElementById('quick-element-select').addEventListener('change',e=>this.act(()=>{this.world.power.select(e.target.value);this.savePreferences();this.update();}));document.getElementById('quick-bind-power').addEventListener('click',()=>{this.world.power.cancel();this.bindings.rebind('power','KeyH');this.world.easyPowerKey=true;this.onKeyMode?.();try{localStorage.setItem('kinetic-easy-power-key','true');}catch{}this.update();});document.getElementById('quick-key-mode').addEventListener('click',()=>{this.world.power.cancel();this.world.easyPowerKey=!this.world.easyPowerKey;this.onKeyMode?.();try{localStorage.setItem('kinetic-easy-power-key',String(this.world.easyPowerKey));}catch{}this.update();});document.getElementById('field-quick-powers').addEventListener('click',()=>{this.guide.close();this.setBank('quick');});document.querySelectorAll('[data-quick-element]').forEach(b=>b.addEventListener('click',()=>this.act(()=>{this.world.power.select(b.dataset.quickElement);this.savePreferences();this.update();})));document.querySelectorAll('[data-quick-action]').forEach(b=>b.addEventListener('click',()=>this.act(()=>this.world.power.quick(b.dataset.quickAction))));document.getElementById('quick-show-advanced').addEventListener('click',()=>this.setBank('flow'));document.getElementById('field-easy-powers').addEventListener('click',()=>{this.setBank('quick');document.getElementById('field-menu-panel').hidden=true;document.getElementById('field-menu-toggle').setAttribute('aria-expanded','false');document.getElementById('arena').focus({preventScroll:true});});this.update();}
 act(fn){if(this.isPaused()||this.world.run.blocked()||this.world.boss.blocked()||this.world.over)return;this.awaken();fn();document.getElementById('arena').focus({preventScroll:true});}
 update(){const w=this.world,p=w.power,selected=p.selected,blocked=this.isPaused()||w.run.blocked()||w.boss.blocked()||w.over,ready=w.infusion.ready(w.player),coat=w.infusion.active(w.player);for(const b of document.querySelectorAll('[data-quick-element]')){b.setAttribute('aria-pressed',String(b.dataset.quickElement===selected));b.disabled=blocked;}
 document.getElementById('quick-bind-power').hidden=this.bindings.bindings.power==='KeyH';document.getElementById('quick-element-select').value=selected;document.getElementById('quick-extras').classList.toggle('fusion-ready',!!ready);const keyButton=document.getElementById('quick-key-mode');keyButton.setAttribute('aria-pressed',String(!!w.easyPowerKey));keyButton.textContent=(w.easyPowerKey?'Power key = combo · ':'Use power key for combos · ')+this.bindings.shortcut('power');
 const name=token=>root.CombatLab.MOVES[root.CombatLab.BASE[token]]?.name||token,m=MAP[selected];document.getElementById('quick-combo-name').textContent=selected.toUpperCase()+' · hands / kicks / air / clinch';document.getElementById('quick-launch-name').textContent=name(m.launch);document.getElementById('quick-finish-name').textContent=name(m.finish);document.getElementById('quick-heavy-name').textContent=name(selected==='fire'&&(w.player.heat||0)>=35?'m':m.heavy);document.getElementById('quick-coat-name').textContent=['wind','stretch'].includes(selected)?'Use Fire, Water, Earth or Lightning':coat?.element===selected?'Remove '+selected+' coating':'Coat with '+selected;document.getElementById('quick-fusion-name').textContent=ready?ready.name:'Coat / cast two different elements';
 for(const b of document.querySelectorAll('[data-quick-action]'))b.disabled=blocked||b.dataset.quickAction==='coat'&&['wind','stretch'].includes(selected)||b.dataset.quickAction==='fusion'&&!ready;
 document.getElementById('quick-power-help').textContent=ready?'Fusion ready: '+ready.name+'. Tap Fusion to release.':w.player.windEnergy<18&&!w.freePlayer()?'Low focus: Combo falls back to hands and kicks while it recovers.':w.grapple?.owner===w.player?'In the clinch: Combo mixes knee, strike and throw. Launch lifts; Finish throws.':'Pick an element, tap Combo to chain. Launch lifts; Finish ends a chain. One tap requests one move. Big cast needs no hold.';
 }
}
root.CombatQuickPowers={MAP,QuickPowers};if(typeof module!=='undefined')module.exports=root.CombatQuickPowers;
})(typeof window!=='undefined'?window:globalThis);
